var ids=['signin','new-conversation','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];var changed=0;doc.pages.filter(p=>/^Proto macOS (Light|Dark)$/.test(p.name)).forEach(p=>p.layers.filter(s=>s.name.indexOf('Screen/macos/')===0&&ids.indexOf(s.name.split('/').pop())>=0).forEach(s=>{function walk(l){if(/^link:.* \d+$/.test(l.name)){l.name=l.name.replace(/ \d+$/,'');changed++;}(l.layers||[]).forEach(walk);}walk(s);}));H.out({changed:changed});